SELECT CAST(COUNT(DISTINCT T1.molecule_id) AS REAL) * 100 / (
  SELECT COUNT(DISTINCT molecule_id) FROM molecule
) FROM bond AS T1 WHERE T1.bond_type = '#'

SELECT
  (SELECT COUNT(bond_id) FROM bond WHERE molecule_id = 'TR006' AND bond_type = '=') AS double_bond_count,
  (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS is_carcinogenic;

SELECT (
    SELECT GROUP_CONCAT(atom_id)
    FROM atom
    WHERE molecule_id = 'TR346'
) AS atom_ids,
(
    SELECT COUNT(DISTINCT bond_type)
    FROM bond
    WHERE molecule_id = 'TR346'
) AS bond_type_count;

SELECT (
    SELECT GROUP_CONCAT(atom_id)
    FROM atom
