SELECT
  T1.id,
  (
    CAST( (SELECT COUNT(id) FROM cards WHERE isStorySpotlight = 1 AND isTextless = 0) AS REAL) * 100.0
  ) / (
    SELECT COUNT(id) FROM cards WHERE isStorySpotlight = 1
  ) AS percentage
FROM cards AS T1
WHERE T1.isStorySpotlight = 1 AND T1.isTextless = 0;

SELECT (
    SELECT Consumption
    FROM yearmonth
    WHERE CustomerID = 7 AND Date = '201304'
) - (
    SELECT Consumption
    FROM yearmonth
    WHERE CustomerID = 5 AND Date = '201304'
);
